Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN=300;
const int MAXM=900000;
int n, t;
int level[MAXN], adj[MAXN], copy_adj[MAXN], fila[MAXN];
int to[MAXM], ant[MAXM], cap[MAXM], pa;
int S, T;
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};
char gr[21][21], gr2[21][21];
int inds[21][21], inds2[21][21], mk[21][21], c[21][21];
int in;
pair<int,int> q[MAXN];
int rp, cp;

void add(int f, int t, int c) {
    to[pa]=t; cap[pa]=c; ant[pa]=adj[f]; adj[f]=pa++;
    to[pa]=f; cap[pa]=0; ant[pa]=adj[t]; adj[t]=pa++;
}

bool valid(int a, int b) {
    return a>=0 && a<n && b>=0 && b<n;
}

void bfs_search(int a, int b) {
    int ini=0, fim=0;
    memset(mk,0,sizeof(mk));
    memset(c,-1,sizeof(c));
    for (int i=0; i<n; i++) for (int j=0; j<n; j++) if (gr[i][j]=='Y') mk[i][j]=1;
    q[fim++]=make_pair(rp,cp);
    q[fim++]=make_pair(a,b);
    c[a][b]=c[rp][cp]=0;
    mk[a][b]=1;
    mk[rp][cp]=2;
    while (ini<fim) {
        auto now=q[ini++];
        int x=now.first, y=now.second;
        if (mk[x][y]==1 && gr2[x][y]>'0' && gr2[x][y]<='9') {
            add(inds[a][b], inds2[x][y], 9);
        }
        if (mk[x][y]==1 && c[x][y]==t) continue;
        for (int i=0; i<4; i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (valid(nx,ny) && mk[nx][ny]==0) {
                mk[nx][ny]=mk[x][y];
                c[nx][ny]=c[x][y]+1;
                q[fim++]=make_pair(nx,ny);
            } else if (mk[x][y]==1 && valid(nx,ny) && mk[nx][ny]==2 && c[nx][ny]==c[x][y]+1 && gr2[nx][ny]>'0' && gr2[nx][ny]<='9') {
                add(inds[a][b], inds2[nx][ny], 9);
            }
        }
    }
}

int bfs(int source, int sink) {
    memset(level,-1,sizeof(level));
    level[source]=0;
    int pos=0, tam=0;
    fila[tam++]=source;
    while (pos<tam) {
        int now=fila[pos++];
        for (int i=adj[now]; i>=0; i=ant[i]) {
            if (cap[i] && level[to[i]]==-1) {
                level[to[i]]=level[now]+1;
                fila[tam++]=to[i];
            }
        }
    }
    return level[sink]!=-1;
}

int dfs(int no, int sink, int flow) {
    if (no==sink) return flow;
    for (int &i=copy_adj[no]; i>=0; i=ant[i]) {
        if (cap[i] && level[no]+1==level[to[i]]) {
            int nflow=dfs(to[i], sink, min(flow, cap[i]));
            if (nflow) {
                cap[i]-=nflow; cap[i^1]+=nflow;
                return nflow;
            }
        }
    }
    return 0;
}

int maxflow(int source, int sink) {
    int mf=0;
    while (true) {
        if (bfs(source, sink)) {
            memcpy(copy_adj, adj, sizeof(adj));
            while (true) {
                int add=dfs(source, sink, 1<<30);
                if (add) mf+=add;
                else break;
            }
        } else break;
    }
    return mf;
}

int main() {
    cin >> n >> t;
    S=202; T=203;
    memset(adj, -1, sizeof(adj));
    pa=0; in=0;
    memset(inds, -1, sizeof(inds));
    memset(inds2, -1, sizeof(inds2));
    for (int i=0; i<n; i++) {
        cin >> gr[i];
        for (int j=0; j<n; j++) {
            if (gr[i][j]>'0' && gr[i][j]<='9') {
                add(S, in, gr[i][j]-'0');
                inds[i][j]=in++;
            }
            if (gr[i][j]=='Z') rp=i, cp=j;
        }
    }
    for (int i=0; i<n; i++) {
        cin >> gr2[i];
        for (int j=0; j<n; j++) {
            if (gr2[i][j]>'0' && gr2[i][j]<='9') {
                add(in, T, gr2[i][j]-'0');
                inds2[i][j]=in++;
            }
        }
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            if (gr[i][j]>'0' && gr[i][j]<='9' && gr2[i][j]>'0' && gr2[i][j]<='9') add(inds[i][j], inds2[i][j], 9);
            if (gr[i][j]>'0' && gr[i][j]<='9') bfs_search(i,j);
        }
    }
    cout << maxflow(S, T) << "\n";
    return 0;
}
